create temporary table b24p2_before(fn text primary key, fn_oid oid not null, pre_src text not null, pre_def text not null, attrs_md5 text not null) on commit drop;
create temporary table b24p2_state(certified text not null, ready_masked text not null, moved text) on commit drop;
create function pg_temp.b24_attrs(p_oid oid) returns text language sql stable as $f$
  select md5(concat_ws('|', p.proowner::text, coalesce(p.proacl::text, ''), p.prosecdef::text, p.proisstrict::text, p.provolatile::text,
    p.proleakproof::text, p.proparallel::text, p.prolang::text, p.procost::text, p.prorows::text, p.prorettype::text, p.proargtypes::text,
    coalesce(p.proargnames::text, ''), coalesce(p.proargmodes::text, ''), coalesce(p.proallargtypes::text, ''), coalesce(p.proconfig::text, ''),
    p.prokind::text, coalesce(obj_description(p.oid, 'pg_proc'), '')))
  from pg_proc p where p.oid = p_oid
$f$;

do $pre$
declare
  r record; v_oid oid; v_src text; v_n integer; v_certified text; v_ready_def text;
begin
  if (select count(*) from b24p2_targets) <> 14 or (select sum(sites) from b24p2_targets) <> 21 then
    raise exception 'B24P2R_TARGET_TABLE_INVALID' using errcode = '55000';
  end if;
  select sha256 into strict v_certified from private.closure_source_v5 where singleton;
  if v_certified is distinct from (select sha256 from private.closure_erasure_source_v5 where singleton) then
    raise exception 'B24P2R_CERTIFIED_VALUES_DISAGREE' using errcode = '55000';
  end if;
  v_ready_def := pg_get_functiondef('private.retention_ai_source_ready()'::regprocedure);
  if (length(v_ready_def) - length(replace(v_ready_def, v_certified, ''))) <> length(v_certified)
     or (select count(*) from regexp_matches(v_ready_def, '[0-9a-f]{64}', 'g')) <> 1 then
    raise exception 'B24P2R_READY_BINDING_INVALID' using errcode = '55000';
  end if;
  if private.closure_source_digest_v5() is distinct from v_certified or not private.retention_ai_source_ready() then
    raise exception 'B24P2R_CLOSURE_SOURCE_NOT_READY' using errcode = '55000';
  end if;
  if exists (select 1 from private.closure_executions_v5 where state = 'EXECUTING') then
    raise exception 'B24P2R_CLOSURE_IN_FLIGHT' using errcode = '55000';
  end if;
  insert into b24p2_state(certified, ready_masked) values (v_certified,
    (select md5(regexp_replace(prosrc, '[0-9a-f]{64}', '<CERTIFIED>', 'g')) from pg_proc where oid = 'private.retention_ai_source_ready()'::regprocedure));
  for r in select * from b24p2_targets order by fn loop
    select count(*) into v_n from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname || '.' || p.proname = r.fn;
    if v_n <> 1 then raise exception 'B24P2R_FUNCTION_NOT_UNIQUE: % (% found)', r.fn, v_n using errcode = '55000'; end if;
    select p.oid, p.prosrc into v_oid, v_src from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname || '.' || p.proname = r.fn;
    if position('40001' in v_src) > 0 then raise exception 'B24P2R_NOT_APPLIED: %', r.fn using errcode = '55000'; end if;
    v_n := (length(v_src) - length(replace(v_src, '''PT409''', ''))) / 7;
    if v_n <> r.sites then raise exception 'B24P2R_SITE_COUNT_DRIFT: % expected % quoted PT409 sites, found %', r.fn, r.sites, v_n using errcode = '55000'; end if;
    insert into b24p2_before(fn, fn_oid, pre_src, pre_def, attrs_md5) values (r.fn, v_oid, v_src, pg_get_functiondef(v_oid), pg_temp.b24_attrs(v_oid));
  end loop;
end
$pre$;

do $convert$
declare r record; v_new text;
begin
  for r in select fn, pre_def from b24p2_before order by fn loop
    v_new := replace(r.pre_def, '''PT409''', '''40001''');
    if v_new = r.pre_def then raise exception 'B24P2R_NOTHING_TO_REVERT: %', r.fn; end if;
    execute v_new;
  end loop;
end
$convert$;

do $isolate$
declare r record; v_old text; v_new text; v_back text; v_src text;
begin
  select certified into strict v_old from b24p2_state;
  v_new := private.closure_source_digest_v5();
  if v_new is null or v_new = v_old then raise exception 'B24P2R_CHANGE_NOT_IN_THE_DIGEST'; end if;
  for r in select fn, fn_oid, pre_src, pre_def from b24p2_before order by fn loop
    execute r.pre_def;
  end loop;
  v_back := private.closure_source_digest_v5();
  if v_back is distinct from v_old then raise exception 'B24P2R_UNREVIEWED_CHANGE'; end if;
  for r in select fn, pre_def from b24p2_before order by fn loop
    execute replace(r.pre_def, '''PT409''', '''40001''');
  end loop;
  if private.closure_source_digest_v5() is distinct from v_new then raise exception 'B24P2R_DIGEST_NOT_STABLE'; end if;
  update b24p2_state set moved = v_new;
end
$isolate$;

do $rebind$
declare v_old text; v_new text; v_def text;
begin
  select certified, moved into strict v_old, v_new from b24p2_state;
  if v_new is distinct from private.closure_source_digest_v5() then raise exception 'B24P2R_DIGEST_NOT_STABLE'; end if;
  v_def := pg_get_functiondef('private.retention_ai_source_ready()'::regprocedure);
  update private.closure_source_v5 set sha256 = v_new where singleton and sha256 = v_old;
  if not found then raise exception 'B24P2R_CERTIFIED_VALUES_DISAGREE'; end if;
  update private.closure_erasure_source_v5 set sha256 = v_new where singleton and sha256 = v_old;
  if not found then raise exception 'B24P2R_CERTIFIED_VALUES_DISAGREE'; end if;
  execute replace(v_def, v_old, v_new);
end
$rebind$;

do $post$
declare r record; v_old text; v_live text; v_ready text; v_src text; v_n integer; s record;
  v_strict boolean := coalesce(nullif(current_setting('b24.preimage', true), ''), 'strict') <> 'relaxed';
begin
  select * into strict s from b24p2_state;
  v_old := s.certified;
  v_live := private.closure_source_digest_v5();
  select prosrc into strict v_ready from pg_proc where oid = 'private.retention_ai_source_ready()'::regprocedure;
  if (select sha256 from private.closure_source_v5 where singleton) is distinct from v_live
     or (select sha256 from private.closure_erasure_source_v5 where singleton) is distinct from v_live
     or position(v_old in v_ready) > 0
     or (length(v_ready) - length(replace(v_ready, v_live, ''))) <> length(v_live) then
    raise exception 'B24P2R_REBIND_INCOMPLETE';
  end if;
  if md5(regexp_replace(v_ready, '[0-9a-f]{64}', '<CERTIFIED>', 'g')) is distinct from s.ready_masked then
    raise exception 'B24P2R_READINESS_FUNCTION_CHANGED_BEYOND_THE_CONSTANT';
  end if;
  if v_strict and v_live is distinct from '86ba37518263930961e254be85569db75257da53d4725c8c186c632dc11de41b' then
    raise exception 'B24P2R_NOT_BACK_TO_THE_PRE_B24_CERTIFICATE: %', v_live;
  end if;
  if private.retention_ai_source_ready() is distinct from true then raise exception 'B24P2R_SOURCE_NOT_READY'; end if;
  if private.closure_erasure_binding_v5() is null or private.closure_erasure_binding_v5()->>'sourceSha256' is distinct from v_live then
    raise exception 'B24P2R_ERASURE_BINDING_NOT_READY';
  end if;
  for r in select t.fn, t.sites, b.fn_oid, b.pre_src, b.attrs_md5 from b24p2_targets t join b24p2_before b using (fn) order by t.fn loop
    select prosrc into strict v_src from pg_proc where oid = r.fn_oid;
    if position('PT409' in v_src) > 0 then raise exception 'B24P2R_PT409_LEFT: %', r.fn; end if;
    v_n := (length(v_src) - length(replace(v_src, '''40001''', ''))) / 7;
    if v_n <> r.sites then raise exception 'B24P2R_SITE_COUNT_AFTER: % expected %, found %', r.fn, r.sites, v_n; end if;
    if replace(v_src, '''40001''', '''PT409''') is distinct from r.pre_src then raise exception 'B24P2R_CHANGE_BEYOND_THE_CODE: %', r.fn; end if;
    if pg_temp.b24_attrs(r.fn_oid) is distinct from r.attrs_md5 then raise exception 'B24P2R_ATTRIBUTES_CHANGED: %', r.fn; end if;
  end loop;
end
$post$;

drop function pg_temp.b24_attrs(oid);
commit;
